-- -----------------------------------
-- Table structure for `alerts_data_tracker_datewise`
-- -----------------------------------

DROP TABLE IF EXISTS `alerts_data_tracker_datewise`;
CREATE TABLE `alerts_data_tracker_datewise` (
  `id` int(6) NOT NULL AUTO_INCREMENT,
  `number_of_records` int(10) DEFAULT NULL,
  `alerts_data_date` varchar(40) DEFAULT NULL,
  `newtablename` varchar(60) DEFAULT NULL,
  `is_viewalertreportcreated` int(10) DEFAULT '0',
  PRIMARY KEY (`id`)
) ENGINE=MyISAM AUTO_INCREMENT=32 DEFAULT CHARSET=latin1;

